def resolve_bids(world: BidWorld, bids: Dict[int, Tuple[int, float]]) -> Assignment:
    """Resolve sealed bids to maximize allocation welfare (sum of matched surpluses).

    Rent is a transfer payment, so extreme overbids do not lower joint surplus
    even if they leave individual tenants with negative payoff. Malformed bids
    are ignored: they win nothing and leave other bids to resolve normally.
    """
    best: Dict[int, Tuple[float, int]] = {}
    for t in bids:
        # Skip non-integer tenant IDs
        if not isinstance(t, int):
            continue

        entry = bids.get(t)
        # Skip if no bid or malformed bid structure
        if not entry or not isinstance(entry, tuple) or len(entry) != 2:
            continue

        l, amount = entry

        # Validate listing index is integer and in valid range
        if not isinstance(l, int) or not (0 <= l < world.num_listings):
            continue

        # Validate bid amount is a real number (not NaN or infinite)
        if not isinstance(amount, (int, float)) or not math.isfinite(amount):
            continue

        # Check if bid meets asking price
        if amount < world.ask[l]:
            continue

        cur = best.get(l)
        if cur is None or amount > cur[0] or (amount == cur[0] and t < cur[1]):
            best[l] = (float(amount), t)

    pairs = sorted((t, l) for l, (_, t) in best.items())
    total = round(sum(world.values[t][l] - world.costs[l] for t, l in pairs), 2)
    return Assignment(pairs=pairs, total=total, unhoused=world.num_tenants - len(pairs))

